// 代表题 ML 1：X 为 L×d_model，h 能整除 d_model，d_head=d_model/h。
// 此处 Wq=Wk=Wv=Wo=I，所以第 head 个头只读写列 [head*d_head, (head+1)*d_head)。
// 换题若给出投影矩阵：取头之前 Q/K/V 先乘 W，拼头之后整个 out 再乘 Wo。
static double[][] multiHeadAttention(double[][] x, int h) {
    int L = x.length;
    int d = x[0].length;
    int dh = d / h;
    double scale = Math.sqrt(dh);
    double[][] out = new double[L][d];
    for (int head = 0; head < h; head++) {
        int off = head * dh;
        double[][] a = new double[L][L];
        for (int i = 0; i < L; i++) {
            double max = -Double.MAX_VALUE;
            for (int j = 0; j < L; j++) {
                double dot = 0;
                for (int k = 0; k < dh; k++) dot += x[i][off + k] * x[j][off + k];
                a[i][j] = dot / scale; // 缩放，避免 d_head 变大时 softmax 饱和
                if (a[i][j] > max) max = a[i][j];
            }
            double sum = 0;
            for (int j = 0; j < L; j++) {
                a[i][j] = Math.exp(a[i][j] - max); // 减 max 防 exp 溢出
                sum += a[i][j];
            }
            for (int j = 0; j < L; j++) a[i][j] /= sum;
        }
        for (int i = 0; i < L; i++) {
            for (int k = 0; k < dh; k++) {
                double v = 0;
                for (int j = 0; j < L; j++) v += a[i][j] * x[j][off + k];
                out[i][off + k] = v;
            }
        }
    }
    return out;
}

