class Solution {
    // qHeads/kHeads/vHeads 形状均为 [heads][sequenceLength][headDim]。
    // 为突出 MHA 核心，这里假设 Q/K/V 已经完成线性投影和分头。
    public double[][] multiHeadAttention(double[][][] qHeads,
                                         double[][][] kHeads,
                                         double[][][] vHeads) {
        int heads = qHeads.length;
        int length = qHeads[0].length;
        int headDim = qHeads[0][0].length;
        double[][] output = new double[length][heads * headDim];

        for (int h = 0; h < heads; h++) {
            double[][] headOutput = scaledDotProductAttention(
                    qHeads[h], kHeads[h], vHeads[h]);

            // 沿最后一维拼接，位置 h*headDim+d 对应第 h 个头。
            for (int i = 0; i < length; i++) {
                for (int d = 0; d < headDim; d++) {
                    output[i][h * headDim + d] = headOutput[i][d];
                }
            }
        }

        return output; // 实际 Transformer 中还会再乘 W_O。
    }

    private double[][] scaledDotProductAttention(double[][] q,
                                                  double[][] k,
                                                  double[][] v) {
        int length = q.length;
        int dim = q[0].length;
        double scale = Math.sqrt(dim);
        double[][] answer = new double[length][dim];

        for (int i = 0; i < length; i++) {
            double[] scores = new double[length];
            double maxScore = -Double.MAX_VALUE;

            // 点积除以 √dₖ，避免维度大时 softmax 过于尖锐。
            for (int j = 0; j < length; j++) {
                double dot = 0.0;
                for (int d = 0; d < dim; d++) {
                    dot += q[i][d] * k[j][d];
                }
                scores[j] = dot / scale;
                maxScore = Math.max(maxScore, scores[j]);
            }

            // 先减行最大值再 exp，防止指数溢出。
            double sumExp = 0.0;
            for (int j = 0; j < length; j++) {
                scores[j] = Math.exp(scores[j] - maxScore);
                sumExp += scores[j];
            }

            // 权重乘 V，得到该查询在本头的输出。
            for (int j = 0; j < length; j++) {
                double weight = scores[j] / sumExp;
                for (int d = 0; d < dim; d++) {
                    answer[i][d] += weight * v[j][d];
                }
            }
        }

        return answer;
    }
}

class Solution {
    private static final double EPS = 1e-12;

    public double binaryCrossEntropy(int label, double probabilityPositive) {
        if (label != 0 && label != 1) {
            throw new IllegalArgumentException("label 只能为 0 或 1");
        }

        // 夹在开区间内，避免 log(0)。
        double p = Math.max(EPS, Math.min(1.0 - EPS, probabilityPositive));
        return -(label * Math.log(p) + (1 - label) * Math.log(1.0 - p));
    }

    // 未归一化 logits 上用 log-sum-exp，等价于 -log softmax。
    public double multiClassCrossEntropy(double[] logits, int labelIndex) {
        if (logits == null || logits.length == 0) {
            throw new IllegalArgumentException("logits 不能为空");
        }
        if (labelIndex < 0 || labelIndex >= logits.length) {
            throw new IllegalArgumentException("labelIndex 越界");
        }

        double maxLogit = -Double.MAX_VALUE;
        for (double value : logits) {
            if (!Double.isFinite(value)) {
                throw new IllegalArgumentException("logit 必须是有限数值");
            }
            maxLogit = Math.max(maxLogit, value);
        }

        // 减去 maxLogit 再 exp，避免指数溢出。
        double sumExp = 0.0;
        for (double value : logits) {
            sumExp += Math.exp(value - maxLogit);
        }

        double logSumExp = maxLogit + Math.log(sumExp);
        return logSumExp - logits[labelIndex];
    }
}

class Solution {
    // 自然对数，单位是 nat。
    public double klDivergence(double[] p, double[] q) {
        if (p.length == 0 || p.length != q.length) {
            throw new IllegalArgumentException("P 和 Q 必须非空且维度一致");
        }

        double sumP = 0.0;
        double sumQ = 0.0;
        for (int i = 0; i < p.length; i++) {
            if (!Double.isFinite(p[i]) || !Double.isFinite(q[i]) || p[i] < 0.0 || q[i] < 0.0) {
                throw new IllegalArgumentException("概率必须是有限的非负数");
            }
            sumP += p[i];
            sumQ += q[i];
        }
        // 容差内必须各自加总为 1，才是概率分布。
        if (Math.abs(sumP - 1.0) > 1e-9 || Math.abs(sumQ - 1.0) > 1e-9) {
            throw new IllegalArgumentException("P 和 Q 必须分别归一化为概率分布");
        }

        double kl = 0.0;
        for (int i = 0; i < p.length; i++) {
            // 极限下 0·log(0/q) 记为 0。
            if (p[i] == 0.0) continue;

            // P 有质量而 Q 为 0，该项发散。
            if (q[i] == 0.0) return Double.POSITIVE_INFINITY;

            kl += p[i] * Math.log(p[i] / q[i]);
        }
        return kl;
    }
}

import java.util.*;

class Solution {
    static class Sample {
        double score;
        int label;

        Sample(double score, int label) {
            this.score = score;
            this.label = label;
        }
    }

    public double auc(int[] labels, double[] scores) {
        if (labels.length != scores.length || labels.length == 0) {
            throw new IllegalArgumentException("输入长度不合法");
        }

        Sample[] samples = new Sample[labels.length];
        long positives = 0;
        long negatives = 0;

        for (int i = 0; i < labels.length; i++) {
            if (!Double.isFinite(scores[i])) {
                throw new IllegalArgumentException("score 必须是有限数值");
            }
            if (labels[i] == 1) positives++;
            else if (labels[i] == 0) negatives++;
            else throw new IllegalArgumentException("label 只能是 0/1");
            samples[i] = new Sample(scores[i], labels[i]);
        }

        // 分母是正负样本配对数，缺一类则 AUC 无定义。
        if (positives == 0 || negatives == 0) {
            throw new IllegalArgumentException("AUC 需要同时存在正、负样本");
        }

        // 升序后，当前组左边的负样本分数都严格更低。
        Arrays.sort(samples, Comparator.comparingDouble(s -> s.score));

        long negativesBefore = 0;
        double favorablePairs = 0.0;
        int i = 0;

        while (i < samples.length) {
            int j = i;
            long groupPos = 0;
            long groupNeg = 0;

            // 同分必须成组，否则平局会被记成全对或全错。
            while (j < samples.length
                    && Double.compare(samples[j].score, samples[i].score) == 0) {
                if (samples[j].label == 1) groupPos++;
                else groupNeg++;
                j++;
            }

            // 严格更高记 1，与本组负样本同分记 0.5。
            favorablePairs += groupPos * negativesBefore;
            favorablePairs += 0.5 * groupPos * groupNeg;

            // 本组负样本只在计分之后才变成“更低分”。
            negativesBefore += groupNeg;
            i = j;
        }

        return favorablePairs / (positives * (double) negatives);
    }
}

import java.util.concurrent.CountDownLatch;

class Solution {
    public void printOneToTen() throws InterruptedException {
        CountDownLatch[] gates = new CountDownLatch[11];
        // 第 0 扇门计数为 0，第一个线程不用等。
        gates[0] = new CountDownLatch(0);
        for (int i = 1; i <= 10; i++) {
            gates[i] = new CountDownLatch(1);
        }

        Thread[] threads = new Thread[10];
        for (int i = 0; i < 10; i++) {
            final int index = i;
            threads[i] = new Thread(() -> {
                try {
                    // 等前一个线程 countDown 后才打印。
                    gates[index].await();
                    System.out.println(index + 1);
                    gates[index + 1].countDown();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            });
            threads[i].start();
        }

        for (Thread thread : threads) {
            thread.join();
        }
    }
}

import java.util.*;
import java.util.concurrent.locks.*;

class Solution {
    private final Lock lock = new ReentrantLock();
    private final Condition turnChanged = lock.newCondition();
    private int nextRow = 0;

    public void printRowsAlternately(int[][] matrix) throws InterruptedException {
        Thread evenIndexThread = new Thread(() -> printParity(matrix, 0), "even-index-row");
        Thread oddIndexThread = new Thread(() -> printParity(matrix, 1), "odd-index-row");

        evenIndexThread.start();
        oddIndexThread.start();

        evenIndexThread.join();
        oddIndexThread.join();
    }

    private void printParity(int[][] matrix, int parity) {
        while (true) {
            lock.lock();
            try {
                // 不是自己的奇偶行就等待，避免抢先打印。
                while (nextRow < matrix.length && nextRow % 2 != parity) {
                    turnChanged.await();
                }

                // 唤醒对方，否则它会停在 await 无法结束。
                if (nextRow >= matrix.length) {
                    turnChanged.signalAll();
                    return;
                }

                System.out.println(Arrays.toString(matrix[nextRow]));
                nextRow++;
                // 交出行号后再唤醒，对方才能通过奇偶检查。
                turnChanged.signalAll();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            } finally {
                lock.unlock();
            }
        }
    }
}

import java.util.concurrent.Semaphore;
import java.util.concurrent.locks.ReentrantLock;

class DiningPhilosophers {
    private final ReentrantLock[] forks = new ReentrantLock[5];
    private final Semaphore limit = new Semaphore(4);

    public DiningPhilosophers() {
        for (int i = 0; i < 5; i++) {
            forks[i] = new ReentrantLock();
        }
    }

    public void wantsToEat(
            int philosopher,
            Runnable pickLeftFork,
            Runnable pickRightFork,
            Runnable eat,
            Runnable putLeftFork,
            Runnable putRightFork) throws InterruptedException {

        int left = philosopher;
        int right = (philosopher + 1) % 5;

        limit.acquire();
        forks[left].lock();
        forks[right].lock();

        try {
            pickLeftFork.run();
            pickRightFork.run();
            eat.run();
            putRightFork.run();
            putLeftFork.run();
        } finally {
            forks[right].unlock();
            forks[left].unlock();
            limit.release();
        }
    }
}

import java.util.Arrays;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class ConcurrentSquareCalculator {
    public int[] squareAll(int[] nums) throws InterruptedException {
        int[] result = new int[nums.length];

        // 限制线程数，不为每个数单独 new 线程
        ExecutorService executor = Executors.newFixedThreadPool(
                Math.min(nums.length, Runtime.getRuntime().availableProcessors())
        );

        CountDownLatch latch = new CountDownLatch(nums.length); // 减到 0 才表示全部算完

        for (int i = 0; i < nums.length; i++) {
            final int index = i; // 捕获本次下标，避免循环变量变化后写错位置
            executor.execute(() -> {
                try {
                    // 每个任务只写自己的下标，写之间互不覆盖
                    result[index] = nums[index] * nums[index];
                } finally {
                    latch.countDown();
                }
            });
        }

        // 等全部任务结束再打印，顺序才与输入一致
        latch.await();
        executor.shutdown();

        System.out.println(Arrays.toString(result));
        return result;
    }
}

final class Singleton {
    // volatile：写入对其他线程可见，并禁止 new 的关键重排序。
    private static volatile Singleton instance;

    // 私有构造，外部不能直接 new。
    private Singleton() {}

    public static Singleton getInstance() {
        // 已创建则不加锁。
        if (instance == null) {
            synchronized (Singleton.class) {
                // 防止排队进来的线程再次 new。
                if (instance == null) {
                    instance = new Singleton();
                }
            }
        }
        return instance;
    }
}
